import io.flutter.embedding.android.FlutterFragmentActivity

// 권한 요청에 ComponentActivity 가 필요하다 — 기본 FlutterActivity 가 아니라 FlutterFragmentActivity
class MainActivity : FlutterFragmentActivity()

steps.code:
// 호출하는 순간 시스템 창이 뜬다(이미 답한 권한이면 바로 돌아온다). initialize 전에도 부를 수 있다.
switch (await OneS1ght.requestPermission()) {
  case PermissionStatus.authorized:
    break;
  case PermissionStatus.denied:
    showSettingsGuide(); // 앱에서 다시 물을 수 없다 — 설정 앱으로 안내
  case PermissionStatus.unsupported:
    showUnsupportedNotice(); // 측위 불가 기기 — 창 없이 돌아온다
}

// iOS 27.2 이상: 층을 찾으려면 위치 권한이 '항상' 이어야 한다. SDK 는 요청하지 않는다 —
// '앱 사용 중' 이 허용된 뒤 앱이 한 번 요청한다(예: permission_handler 패키지).
// ⚠️ permission_handler 는 접두사로 가져온다 — PermissionStatus 이름이 SDK 와 겹친다.
//    import 'package:permission_handler/permission_handler.dart' as ph;
if (Platform.isIOS) {
  await ph.Permission.locationAlways.request();
}

// 최초 1회 발급받아 앱에 보관(예: shared_preferences)하고, 매 실행 그 값을 연결한다.
var profileId = await loadSavedProfileId();
if (profileId == null) {
  profileId = await OneS1ght.createProfile({
    'gender': 'F',
    'ageBand': '20s', // 정확한 나이가 아니라 연령대
  });
  await saveProfileId(profileId);
}
await OneS1ght.identify(profileId: profileId);

final buildings = await OneS1ght.buildings();
final floors = await OneS1ght.floors(buildingId: buildings.first.id);
// 처음 지정할 때는 buildingId 를 함께 넘긴다(없으면 E3001). setFloorMap(null) 은 층을 비운다.
await OneS1ght.setFloorMap(floors.first, buildingId: buildings.first.id);

// 또는 엔진이 찾은 층을 따라간다
final session = await OneS1ght.floorSession();
session.onFloorDetected.listen((floorId) async {
  if (floorId == null) return; // 층을 잃음
  final floor = await OneS1ght.floor(buildingId: buildings.first.id, floorId: floorId);
  await OneS1ght.setFloorMap(floor, buildingId: buildings.first.id);
});

// floors() 목록은 image 가 비어 있다 — 그릴 층만 단건으로 받는다.
final floor = await OneS1ght.floor(buildingId: buildingId, floorId: floorId);
final plan = floor.image == null ? null : Image.memory(floor.image!);
// 좌표는 도면 로컬 미터 — originX·originY·widthM·heightM 으로 화면 좌표로 바꾼다.
Offset toScreen(Coordinates c, Size canvas) => Offset(
      (c.x - floor.originX) / floor.widthM * canvas.width,
      canvas.height - (c.y - floor.originY) / floor.heightM * canvas.height,
    );

final session = await OneS1ght.floorSession(); // 항상 같은 인스턴스
session.onZoneEnter.listen((zone) => debugPrint('IN  ${zone.name}'));
session.onZoneExit.listen((zone) => debugPrint('OUT ${zone.name}'));
session.onZoneDwell.listen((d) => debugPrint('DWELL ${d.zone.name} ${d.seconds}s'));
session.onPosition.listen((c) => debugPrint('${c.x}, ${c.y}')); // 도면 로컬 미터
session.onTriggers.listen((t) {
  for (final trigger in t.triggers) {
    debugPrint('${t.zoneId} ${trigger.type}'); // signage · coupon · tracking · merch · generic (늘 수 있다)
  }
});
session.onStopped.listen((reason) {
  if (reason == StopReason.engineFailed) {
    // 권한·Bluetooth 등 원인을 풀고 begin() 으로 다시 연다
  }
});
await session.begin();

final session = await OneS1ght.floorSession();
await session.pause(); // 좌표 표시·수집·판정만 멈춤 — 엔진은 층을 계속 잡고 있다
await session.resume(); // 바로 이어진다

Timer? debounce;
(await OneS1ght.floorSession()).onConfigChanged.listen((change) {
  switch (change) {
    case ZonesChanged() || ResyncNeeded():
      // 연달아 오면 1초 모았다가 한 번만 — 구역을 다시 물릴 때마다 판정이 처음부터 시작된다
      debounce?.cancel();
      debounce = Timer(const Duration(seconds: 1), OneS1ght.refreshZones);
    case PlanChanged(:final floorId):
      redrawFloor(floorId); // floor() 로 다시 받아 지도를 다시 그린다
    case RulesChanged(:final zoneId):
      recheckZoneEvents(zoneId); // 지금 들어가 있는 구역이면 그 구역의 이벤트를 한 번 다시 조회
    default:
      break;
  }
});

switch (await OneS1ght.deviceAvailability()) {
  case DeviceAvailability.available:
    break;
  case DeviceAvailability.osVersionTooLow:
    showNotice('OS 업데이트 후 사용할 수 있습니다');
  case DeviceAvailability.deviceNotSupported:
    showNotice('이 기기는 실내 측위를 지원하지 않습니다');
}

if (kDebugMode) {
  OneS1ght.onDebugLog.listen((log) => debugPrint('OneS1ght $log')); // [level] 문구 — E·I 코드 줄 포함
}
await OneS1ght.setLanguage('ko'); // 'ko' · 'ja' · 'en', null 이면 기기 언어
